import{_ as t,o as i,c as a,a2 as o}from"./chunks/framework.DaGSOal_.js";const p=JSON.parse('{"title":"Features","description":"","frontmatter":{"sidebar_position":3},"headers":[],"relativePath":"quick-notes/features.md","filePath":"quick-notes/features.md","lastUpdated":1794046641000}'),r={name:"quick-notes/features.md"};function l(n,e,s,c,d,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><h2 id="viewport-notes" tabindex="-1">Viewport Notes <a class="header-anchor" href="#viewport-notes" aria-label="Permalink to &quot;Viewport Notes&quot;">​</a></h2><h3 id="place-notes-in-3d-space" tabindex="-1">Place Notes in 3D Space <a class="header-anchor" href="#place-notes-in-3d-space" aria-label="Permalink to &quot;Place Notes in 3D Space&quot;">​</a></h3><p>Right-click anywhere in the Viewport to place a sticky note at that exact world location. The note appears as a colored card floating above the position with a visual connector line showing its anchor point.</p><h3 id="visual-indicators" tabindex="-1">Visual Indicators <a class="header-anchor" href="#visual-indicators" aria-label="Permalink to &quot;Visual Indicators&quot;">​</a></h3><ul><li><strong>Color-coded categories:</strong> TODO (blue), BUG (red), INFO (yellow), REMINDER (green)</li><li><strong>Priority badges:</strong> Visual indicators for Low, Medium, High priority</li><li><strong>Connector lines:</strong> Show exact placement in 3D space</li><li><strong>Editor-only option:</strong> Hide notes during Play-In-Editor for clean testing</li></ul><h3 id="context-preservation" tabindex="-1">Context Preservation <a class="header-anchor" href="#context-preservation" aria-label="Permalink to &quot;Context Preservation&quot;">​</a></h3><p>Notes stay exactly where you placed them. When you return to that area weeks later, your note is still there reminding you what needs to be done.</p><h2 id="blueprint-notes" tabindex="-1">Blueprint Notes <a class="header-anchor" href="#blueprint-notes" aria-label="Permalink to &quot;Blueprint Notes&quot;">​</a></h2><h3 id="attach-to-specific-nodes" tabindex="-1">Attach to Specific Nodes <a class="header-anchor" href="#attach-to-specific-nodes" aria-label="Permalink to &quot;Attach to Specific Nodes&quot;">​</a></h3><p>Right-click any Blueprint node to attach a note directly to it. The note is linked to that specific node via GUID, so even if you move or reorganize your Blueprint, the note stays attached.</p><h3 id="jump-to-blueprint" tabindex="-1">Jump to Blueprint <a class="header-anchor" href="#jump-to-blueprint" aria-label="Permalink to &quot;Jump to Blueprint&quot;">​</a></h3><p>Click any Blueprint note in the Overview Panel and it will:</p><ol><li>Open the Blueprint Editor</li><li>Navigate to the exact graph</li><li>Focus on the specific node</li><li>Highlight the note for you</li></ol><p>Perfect for tracking complex logic issues or marking nodes that need refactoring.</p><h2 id="overview-panel" tabindex="-1">Overview Panel <a class="header-anchor" href="#overview-panel" aria-label="Permalink to &quot;Overview Panel&quot;">​</a></h2><h3 id="centralized-management" tabindex="-1">Centralized Management <a class="header-anchor" href="#centralized-management" aria-label="Permalink to &quot;Centralized Management&quot;">​</a></h3><p>Access all your notes from <strong>Tools → Quick Notes</strong>. The Overview Panel gives you a bird&#39;s-eye view of everything that needs attention across your entire project.</p><h3 id="search-filter" tabindex="-1">Search &amp; Filter <a class="header-anchor" href="#search-filter" aria-label="Permalink to &quot;Search &amp; Filter&quot;">​</a></h3><ul><li><strong>Text search:</strong> Find notes by title or description</li><li><strong>Filter by source:</strong> Show only Viewport or Blueprint notes</li><li><strong>Filter by status:</strong> Hide resolved notes or show only unresolved</li><li><strong>Sort options:</strong> Organize by priority, date, or category</li></ul><h3 id="one-click-navigation" tabindex="-1">One-Click Navigation <a class="header-anchor" href="#one-click-navigation" aria-label="Permalink to &quot;One-Click Navigation&quot;">​</a></h3><p>Click any note to jump directly to it:</p><ul><li><strong>Viewport notes:</strong> Camera moves to the note location</li><li><strong>Blueprint notes:</strong> Opens the Blueprint and focuses on the node</li></ul><h3 id="mark-as-resolved" tabindex="-1">Mark as Resolved <a class="header-anchor" href="#mark-as-resolved" aria-label="Permalink to &quot;Mark as Resolved&quot;">​</a></h3><p>Don&#39;t want to delete a note but want to track it as done? Mark it as resolved to keep it in your history without cluttering your active list.</p><h2 id="note-categories" tabindex="-1">Note Categories <a class="header-anchor" href="#note-categories" aria-label="Permalink to &quot;Note Categories&quot;">​</a></h2><h3 id="todo" tabindex="-1">TODO <a class="header-anchor" href="#todo" aria-label="Permalink to &quot;TODO&quot;">​</a></h3><ul><li>Default category for general tasks</li><li>Blue color coding</li><li>Perfect for feature work and improvements</li></ul><h3 id="bug" tabindex="-1">BUG <a class="header-anchor" href="#bug" aria-label="Permalink to &quot;BUG&quot;">​</a></h3><ul><li>Red color coding for critical issues</li><li>High visibility for problems that need fixing</li><li>Easy to spot during playtesting</li></ul><h3 id="info" tabindex="-1">INFO <a class="header-anchor" href="#info" aria-label="Permalink to &quot;INFO&quot;">​</a></h3><ul><li>Yellow color for informational notes</li><li>Document design decisions or important context</li><li>Reference material for you or your team</li></ul><h3 id="reminder" tabindex="-1">REMINDER <a class="header-anchor" href="#reminder" aria-label="Permalink to &quot;REMINDER&quot;">​</a></h3><ul><li>Green color for time-sensitive tasks</li><li>Don&#39;t forget important deadlines or follow-ups</li><li>Set priorities to track urgency</li></ul><h2 id="priority-system" tabindex="-1">Priority System <a class="header-anchor" href="#priority-system" aria-label="Permalink to &quot;Priority System&quot;">​</a></h2><h3 id="low-priority" tabindex="-1">Low Priority <a class="header-anchor" href="#low-priority" aria-label="Permalink to &quot;Low Priority&quot;">​</a></h3><ul><li>Nice-to-have improvements</li><li>Polish and refinement tasks</li><li>Can be deferred if needed</li></ul><h3 id="medium-priority" tabindex="-1">Medium Priority <a class="header-anchor" href="#medium-priority" aria-label="Permalink to &quot;Medium Priority&quot;">​</a></h3><ul><li>Important but not blocking</li><li>Should be addressed soon</li><li>Default priority level</li></ul><h3 id="high-priority" tabindex="-1">High Priority <a class="header-anchor" href="#high-priority" aria-label="Permalink to &quot;High Priority&quot;">​</a></h3><ul><li>Critical issues or must-have features</li><li>Blocks progress or affects quality</li><li>Visual indicator helps them stand out</li></ul><h2 id="export-functionality" tabindex="-1">Export Functionality <a class="header-anchor" href="#export-functionality" aria-label="Permalink to &quot;Export Functionality&quot;">​</a></h2><h3 id="text-file-export" tabindex="-1">Text File Export <a class="header-anchor" href="#text-file-export" aria-label="Permalink to &quot;Text File Export&quot;">​</a></h3><p>Export all your notes to a <code>.txt</code> file:</p><ol><li>Click <strong>Export</strong> in the Overview Panel</li><li>Choose save location</li><li>File is organized by source with full context</li></ol><h3 id="what-s-included" tabindex="-1">What&#39;s Included <a class="header-anchor" href="#what-s-included" aria-label="Permalink to &quot;What&#39;s Included&quot;">​</a></h3><p>Each note in the export shows:</p><ul><li>Title and description</li><li>Category and priority</li><li>Source (Viewport location or Blueprint path)</li><li>Creation date</li><li>Resolved status</li></ul><h3 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h3><ul><li><strong>Team Handoffs:</strong> Share your notes with other developers</li><li><strong>Milestone Archives:</strong> Keep a record of what was tracked</li><li><strong>Task Lists:</strong> Generate TODO lists for sprint planning</li><li><strong>Bug Reports:</strong> Export bug notes for QA documentation</li></ul><h2 id="error-diagnostic-codes" tabindex="-1">Error Diagnostic Codes <a class="header-anchor" href="#error-diagnostic-codes" aria-label="Permalink to &quot;Error Diagnostic Codes&quot;">​</a></h2><p>Quick Notes uses error codes (QN-100 to QN-700) for easy troubleshooting:</p><ul><li><strong>QN-100 series:</strong> Initialization and setup</li><li><strong>QN-200 series:</strong> Viewport note operations</li><li><strong>QN-300 series:</strong> Blueprint note operations</li><li><strong>QN-400 series:</strong> Overview panel operations</li><li><strong>QN-500 series:</strong> Export functionality</li><li><strong>QN-600 series:</strong> Data storage</li><li><strong>QN-700 series:</strong> UI and rendering</li></ul><p>If something goes wrong, check the Output Log for the error code and share it with support for instant diagnosis.</p><h2 id="performance-runtime" tabindex="-1">Performance &amp; Runtime <a class="header-anchor" href="#performance-runtime" aria-label="Permalink to &quot;Performance &amp; Runtime&quot;">​</a></h2><h3 id="zero-runtime-impact" tabindex="-1">Zero Runtime Impact <a class="header-anchor" href="#zero-runtime-impact" aria-label="Permalink to &quot;Zero Runtime Impact&quot;">​</a></h3><p>Quick Notes is <strong>editor-only</strong>. The plugin:</p><ul><li>Does not load in packaged builds</li><li>Has no runtime performance cost</li><li>Is completely stripped from shipping builds</li><li>Uses no memory in your final game</li></ul><h3 id="efficient-in-editor" tabindex="-1">Efficient in Editor <a class="header-anchor" href="#efficient-in-editor" aria-label="Permalink to &quot;Efficient in Editor&quot;">​</a></h3><ul><li>Notes update only when edited</li><li>Minimal viewport rendering cost</li><li>No frame rate impact during normal work</li><li>Efficient data storage</li></ul><h2 id="data-management" tabindex="-1">Data Management <a class="header-anchor" href="#data-management" aria-label="Permalink to &quot;Data Management&quot;">​</a></h2><h3 id="local-storage" tabindex="-1">Local Storage <a class="header-anchor" href="#local-storage" aria-label="Permalink to &quot;Local Storage&quot;">​</a></h3><p>All notes are stored locally in your project:</p><ul><li>No cloud dependencies</li><li>No network calls</li><li>Fast and reliable</li><li>Private and secure</li></ul><h3 id="version-control" tabindex="-1">Version Control <a class="header-anchor" href="#version-control" aria-label="Permalink to &quot;Version Control&quot;">​</a></h3><p>By default, note data is not included in version control. This is intentional - notes are personal workflow tools. If you want to share notes with your team, use the export functionality.</p><h2 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;Support&quot;">​</a></h2><p>Need help? Contact us:</p><ul><li><a href="https://discord.gg/UJCnVjwTTt" target="_blank" rel="noreferrer">Deblx Dev Discord</a> - Fast community support</li><li><a href="https://deblx.com/help" target="_blank" rel="noreferrer">Deblx Help Center</a> - Submit a support request</li><li>Include error codes (QN-XXX) for faster diagnosis</li></ul>',69)])])}const g=t(r,[["render",l]]);export{p as __pageData,g as default};
